def digest(raw):
    return hashlib.sha256(raw).hexdigest()


class CreatorShelfRefreshHistoryTests(unittest.TestCase):
    def setUp(self):
        self.directory = tempfile.TemporaryDirectory()
        self.addCleanup(self.directory.cleanup)
        self.root = Path(self.directory.name)
        self.post = {name: (ROOT / name).read_bytes() for name in history.SOURCE_SHA256}
        self.pre = {}
        for name, raw in self.post.items():
            restored = raw
            for offset, after, before in reversed(TEST_INVERSE_DELTAS[name]):
                self.assertEqual(restored.count(after), 1)
                self.assertEqual(restored[offset:offset + len(after)], after)
                restored = restored[:offset] + before + restored[offset + len(after):]
            self.pre[name] = restored
            self.assertEqual(digest(raw), history.SOURCE_SHA256[name][1])
            self.assertEqual(digest(restored), history.SOURCE_SHA256[name][0])
        self.install(self.post)

    def install(self, sources):
        for name, raw in sources.items():
            path = self.root / name
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_bytes(raw)

    def project(self):
        return history.historical_pre_shelf_refresh_mine_bytes(root=self.root)

    def rejects(self, sources):
        self.install(sources)
        with self.assertRaises(ValueError):
            self.project()

    def test_both_complete_states_restore_only_exact_original_mine_bytes(self):
        for sources in (self.pre, self.post):
            self.install(sources)
            self.assertEqual(self.project(), self.pre[history.MINE_SOURCE])
            self.assertEqual(self.project(), self.pre[history.MINE_SOURCE])
            for name, raw in sources.items():
                self.assertEqual((self.root / name).read_bytes(), raw)
        self.assertEqual(history.MINE_INVERSE_DELTAS, TEST_INVERSE_DELTAS[history.MINE_SOURCE])

    def test_all_thirty_mixed_bundles_are_rejected(self):
        names = tuple(self.post)
        for states in product((False, True), repeat=5):
            if all(states) or not any(states):
                continue
            with self.subTest(states=states):
                self.rejects({name: (self.post if state else self.pre)[name]
                              for name, state in zip(names, states)})

    def test_each_file_raw_mutations_rejected_in_both_states(self):
        for state, sources in [('old', self.pre), ('new', self.post)]:
            for name, raw in sources.items():
                changes = [raw + b'\n', raw[:-1], b'\xef\xbb\xbf' + raw,
                           raw.replace(b'\n', b'\r\n'), bytes([raw[0] ^ 1]) + raw[1:]]
                for index, changed in enumerate(changes):
                    with self.subTest(state=state, name=name, mutation=index):
                        self.rejects({**sources, name: changed})

    def test_missing_each_file_in_both_states_rejected(self):
        for sources in (self.pre, self.post):
            for name in sources:
                self.install(sources)
                (self.root / name).unlink()
                with self.assertRaisesRegex(ValueError, 'Missing or unreadable'):
                    self.project()

    def test_all_finite_hunks_missing_duplicated_or_moved_rejected(self):
        for name, deltas in TEST_INVERSE_DELTAS.items():
            raw = self.post[name]
            for offset, after, before in deltas:
                missing = raw[:offset] + raw[offset + len(after):]
                for changed in (missing, raw[:offset] + after + raw[offset:], after + missing):
                    with self.subTest(name=name, offset=offset):
                        self.assertNotEqual(changed, raw)
                        self.rejects({**self.post, name: changed})

    def test_later_mutation_cannot_be_hidden_by_cache(self):
        self.project()
        for name in self.post:
            self.rejects({**self.post, name: self.post[name] + b'\n'})
            self.install(self.post)
            self.assertEqual(self.project(), self.pre[history.MINE_SOURCE])

    def test_inverse_rejects_unrecognized_postimage_and_damaged_delta_table(self):
        raw = self.post[history.MINE_SOURCE]
        with self.assertRaises(ValueError):
            history._restore_mine_bytes(raw + b'\n')
        original = history.MINE_INVERSE_DELTAS
        offset, after, before = original[0]
        for damaged in (((offset + 1, after, before),) + original[1:],
                        original + (original[-1],),
                        ((offset, after, before + b'x'),) + original[1:]):
            with patch.object(history, 'MINE_INVERSE_DELTAS', damaged):
                with self.assertRaises(ValueError):
                    history._restore_mine_bytes(raw)

    def test_storage_bundle_is_validated_before_mine_and_other_helpers(self):
        for name in (*storage.APP_SHA256, *storage.PREIMAGE_FILES.values(), storage.EVOLUTION_FILE):
            path = self.root / name
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_bytes((ROOT / name).read_bytes())
        helper = 'App/TemplateAuthoringFixtureSupport.swift'
        (self.root / helper).write_bytes((ROOT / helper).read_bytes())
        for name in storage.APP_SHA256:
            raw = (ROOT / name).read_bytes()
            (self.root / name).write_bytes(raw + b'\n')
            for target in (history.MINE_SOURCE, helper):
                with patch.object(storage, 'historical_pre_shelf_refresh_mine_bytes') as inverse:
                    with self.assertRaisesRegex(ValueError, 'Mixed or unreviewed creator storage'):
                        storage.historical_pre_synthetic_storage_helper_bytes(self.root / target, root=self.root)
                    inverse.assert_not_called()
            (self.root / name).write_bytes(raw)
        self.assertEqual(storage.historical_pre_synthetic_storage_helper_bytes(
            self.root / history.MINE_SOURCE, root=self.root), self.pre[history.MINE_SOURCE])

    def test_storage_connection_and_old_tests_restore_byte_exactly(self):
        raw = (ROOT / 'tools/tests/creator_pending_synthetic_storage_history.py').read_bytes()
        added = b'from tools.tests.creator_shelf_refresh_history import historical_pre_shelf_refresh_mine_bytes\n'
        branch = b"    if relative == 'App/TemplateAuthoringMineView.swift':\n        return historical_pre_shelf_refresh_mine_bytes(root=root)\n"
        self.assertEqual(raw.count(added), 1)
        self.assertEqual(raw.count(branch), 1)
        restored = raw.replace(added, b'', 1).replace(branch, b'', 1)
        self.assertEqual(digest(restored), STORAGE_OLD_SHA256)
        raw = (ROOT / 'tools/tests/test_creator_pending_synthetic_storage_history.py').read_bytes()
        self.assertEqual(raw.count(NEW_STORAGE_TEST_REGION), 1)
        restored = raw.replace(NEW_STORAGE_TEST_REGION, OLD_STORAGE_TEST_REGION, 1)
        self.assertEqual(digest(restored), STORAGE_TEST_OLD_SHA256)


STORAGE_OLD_SHA256 = 'd383a2d728bee6ace5f421f7b7187826cfe911d68995c323e46ad7e20d9395ea'

STORAGE_TEST_OLD_SHA256 = 'd1cbd94fc8406215e80762a72e9d0a454c1bca46a1801f6a11eab633acff7fbd'

if __name__ == '__main__':
    unittest.main()
